--
-- Table structure for table `cards`
--

DROP TABLE IF EXISTS `cards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cards` (
  `created_at` datetime(6) DEFAULT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `id` bigint NOT NULL AUTO_INCREMENT,
  `updated_at` datetime(6) DEFAULT NULL,
  `user_id` bigint NOT NULL,
  `card_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `rarity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `series_id` bigint DEFAULT NULL,
  `pokemon_set_id` bigint DEFAULT NULL,
  `pokemon_id` bigint DEFAULT NULL,
  `tcgdex_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reject_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `category` enum('ENERGY','POKEMON','TRAINERS','UNKNOWN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `grade` enum('BGS_10','PSA_10','PSA_9') COLLATE utf8mb4_unicode_ci NOT NULL,
  `source` enum('MANUAL','TCGDEX') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('ACTIVE','PENDING','REJECTED') COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UKigthbk12f2bio93w9cosk48r8` (`tcgdex_id`),
  KEY `idx_cards_status` (`status`),
  KEY `idx_cards_user_id` (`user_id`),
  KEY `idx_cards_user_id_status` (`user_id`,`status`),
  KEY `idx_cards_grade` (`grade`),
  KEY `idx_cards_category` (`category`),
  KEY `idx_cards_created_at` (`created_at`),
  KEY `fk_cards_series` (`series_id`),
  KEY `fk_cards_pokemon_set` (`pokemon_set_id`),
  KEY `fk_cards_pokemon` (`pokemon_id`),
  CONSTRAINT `fk_cards_pokemon` FOREIGN KEY (`pokemon_id`) REFERENCES `pokemon` (`id`),
  CONSTRAINT `fk_cards_pokemon_set` FOREIGN KEY (`pokemon_set_id`) REFERENCES `pokemon_sets` (`id`),
  CONSTRAINT `fk_cards_series` FOREIGN KEY (`series_id`) REFERENCES `series` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=23194 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

